// Artist Flow Profiles — minimal version with key artists
export interface FlowProfile {
  artistId: string;
  vocalTags: string[];
  cadence: CadenceType;
  cadenceInstruction: string;
  syllablesPerBar: number;
  speedLabel: string;
  breathEveryBars: number;
  breathStyle: string;
  accentPattern: string;
  defaultRhymeScheme: string;  // rs_free, rs_aabb, rs_abab, rs_abba, rs_monorhyme, rs_internal, rs_triplets
  // ===== Phase 1 curation: peak-era style anchors =====
  peakEra: string;  // human-readable peak era window (e.g. "2015-2017 (DS2 / HNDRXX / Future)")
  hookStyle: "repetitive" | "melodic" | "technical" | "simple_punchy";
  wordplayTier: 1 | 2 | 3;  // 1 = heavy wordplay, 3 = minimal
  emotionalArc: "rising" | "flat" | "chaotic" | "introspective";
  melodicContour: "rising" | "falling" | "flat" | "variable";
  // ===== Phase 5 curation: wordplay & storytelling engine =====
  wordplayTechniques: string[];   // specific wordplay techniques the artist uses at peak
  storytellingStyle: string;       // narrative style of the artist at peak
  // ===== Phase 6 curation: song form intelligence =====
  songFormStyle: "expanding_chorus" | "pre_chorus_build" | "beat_drop" | "variable_verse" | "minimal_standard" | "hybrid";  // NEW Phase 6
  imageryBank: string[];  // NEW Phase 7 — concrete specific imagery the artist uses at peak (brands, places, objects, slang, concepts)
  sunoVocalTimbre: string; // Suno AI v4.5 specific vocal descriptor
}

export type CadenceType =
  | "triplet" | "staccato" | "legato" | "swing" | "syncopated"
  | "rapid_fire" | "melodic_flow" | "chaotic" | "conversational" | "free";

